const input = $json.body ?? $json;
const payload = input.payload ?? input;
const suppliedSecret = $headers?.['x-gatherly-secret'] ?? $headers?.['X-Gatherly-Secret'];
if ($env.GATHERLY_WEBHOOK_SECRET && suppliedSecret !== $env.GATHERLY_WEBHOOK_SECRET) {
  throw new Error('Webhook secret is not valid.');
}
const required = [payload.registrationId, payload.attendee?.email, payload.attendee?.name, payload.event?.title];
if (required.some((value) => !value)) {
  throw new Error('The registration payload is missing required fields.');
}
return [{ json: {
  accepted: true,
  eventType: input.type ?? 'registration.created',
  receivedAt: new Date().toISOString(),
  registrationId: payload.registrationId,
  attendee: { name: payload.attendee.name, email: payload.attendee.email },
  event: { title: payload.event.title, location: payload.event.location, startDateTime: payload.event.startDateTime },
  nextAction: 'Connect an email or CRM node here when needed.'
} }];
